//! Actual current QueryDb/source receipt tests; generic page DATA grants no coverage.
use super::*;
use dq_analyze as analyze;
use analyze::captured_reactive_reads::Failure;
use crate::policy_request::WorkspaceAuxiliaryQuestion;
#[path="../../../../analyze/fixtures/native-keys/fixture.rs"]mod initial;
#[path="../../../../analyze/fixtures/native-keys/report.rs"]mod report;
fn initial_root(case:&str)->PathBuf{let root=crate::test_scratch::dir(&format!("keys-current-{case}"));for(relative,bytes)in initial::files(case).unwrap(){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}root}
fn capture<P:SnapshotProvider>(root:&Path,front:&ColdFrontend,inputs:&RecordingInputs<P>,selected:bool)->Arc<workspace_capture::WorkspaceCapture>{workspace_capture::capture_with_auxiliary(front,inputs,discover(root,inputs),&root.join("tools/ci/lint_scopes.toml"),if selected{&[WorkspaceAuxiliaryQuestion::Keys]}else{&[]}).unwrap()}
#[test]
fn actual_keys_selected_snapshots_match_whole_original_case_records_without_io_or_body_queries(){
 for case in initial::CASES{let root=initial_root(case);let physical=Physical{fail_policy:Mutex::new(None),reads:Mutex::new(BTreeMap::new())};let inputs=RecordingInputs::new(&physical,4_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let capture=capture(&root,&front,&inputs,true);let current=snapshot(&front,&db,&inputs,&capture);let before=physical.reads();let body_before=db.db().stats(dm_query::Kind(4)).computed;let mut escaped=None;
 let cold=current.with_native_keys(&current.tree,|data,config,budget|{escaped=Some(Arc::downgrade(budget));Ok(report::record(data,config,&root,case))}).unwrap();let warm=current.with_native_keys(&current.tree,|data,config,_|Ok(report::record(data,config,&root,case))).unwrap();assert_eq!(cold,warm);assert!(escaped.unwrap().upgrade().is_none(),"operation Budget must not be cached in output/source metadata");assert_eq!(physical.reads(),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,body_before);if *case=="basic"{assert_eq!(cold["sites"].as_array().unwrap().len(),16);assert_eq!(cold["allow_used"].as_array().unwrap().len(),1);}println!("NATIVE_KEYS_FULL={cold}");
 }
}
#[test]
fn actual_keys_source_pages_exceed_finite_fixture_and_require_selected_current_full_code_receipt(){
 let root=initial_root("basic");for index in 0..130{std::fs::write(root.join(format!("code/padding-{index}.dm")),b"// original source page without key declarations
").unwrap();}let physical=Physical{fail_policy:Mutex::new(None),reads:Mutex::new(BTreeMap::new())};let inputs=RecordingInputs::new(&physical,4_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let selected=capture(&root,&front,&inputs,true);let current=snapshot(&front,&db,&inputs,&selected);let before=physical.reads();for _ in 0..2{current.with_native_keys(&current.tree,|data,_,_|{assert_eq!(data.sites().len(),16);Ok(())}).unwrap();}assert_eq!(physical.reads(),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
 let unselected=capture(&root,&front,&inputs,false);let unselected_snapshot=snapshot(&front,&db,&inputs,&unselected);let called=std::cell::Cell::new(false);assert!(unselected_snapshot.with_native_keys(&unselected_snapshot.tree,|_,_,_|{called.set(true);Ok(())}).is_err());assert!(!called.get());let foreign=crate::query_db::QueryDb::default();assert!(foreign.with_workspace_keys(&selected,&current.workspace_native_read().unwrap(),|_,_,_|{called.set(true);Ok(())}).is_err());assert!(!called.get());
 // A new root-follow contract requires its own recorder and frontend, never a reused receipt.
 let partial_inputs=RecordingInputs::new(FileSystemInputs,5_000_000_000);let partial_front=frontend(&root,&partial_inputs,&db);let partial_discovery=Arc::new(workspace_discovery::discover(&partial_inputs,DiscoveryContract{root:root.clone(),recursive_roots:vec![root.join("code/modules/keys")]}).unwrap());let partial=workspace_capture::capture_with_auxiliary(&partial_front,&partial_inputs,partial_discovery,&root.join("tools/ci/lint_scopes.toml"),&[WorkspaceAuxiliaryQuestion::Keys]).unwrap();let partial_snapshot=snapshot(&partial_front,&db,&partial_inputs,&partial);assert!(partial_snapshot.with_native_keys(&partial_snapshot.tree,|_,_,_|{called.set(true);Ok(())}).is_err());assert!(!called.get());
}
#[test]
fn actual_keys_same_counter_quota_io_cancellation_unwind_and_missing_manifest_recovery(){
 let root=initial_root("basic");let inputs=RecordingInputs::new(FileSystemInputs,4_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let capture=capture(&root,&front,&inputs,true);let current=snapshot(&front,&db,&inputs,&capture);let guard=current.workspace_native_read().unwrap();let called=std::cell::Cell::new(false);let denied=db.with_workspace_keys_limit(&capture,&guard,256,|_,_,_|{called.set(true);Ok(())}).unwrap_err();assert!(matches!(denied,Failure::Operational(error)if error.kind()==io::ErrorKind::OutOfMemory));assert!(!called.get());
 let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(60));let error=current.with_native_keys(&current.tree,|_,_,_|->io::Result<()>{token.cancel();Err(io::Error::from_raw_os_error(1450))}).unwrap_err();assert!(matches!(error,Failure::Operational(error)if error.raw_os_error()==Some(1450)));let stopped=current.with_native_keys(&current.tree,|_,_,_|{called.set(true);Ok(())}).unwrap_err();assert!(matches!(stopped,Failure::Operational(error)if error.kind()==io::ErrorKind::Interrupted));assert!(!called.get());drop(binding);
 let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _:Result<(),Failure>=current.with_native_keys(&current.tree,|_,_,_|panic!("owned keys consumer unwind"));}));assert!(panic.is_err());current.with_native_keys(&current.tree,|data,_,_|{assert_eq!(data.sites().len(),16);Ok(())}).unwrap();assert!(capture.facts().validate(&FileSystemInputs,true,u128::MAX/2).unwrap().0.unchanged());
 drop(guard);drop(current);std::fs::write(root.join("deepquarry.dme"),b"// actual formerly absent fixed presentation manifest
").unwrap();assert!(!capture.facts().validate(&FileSystemInputs,true,u128::MAX/2).unwrap().0.unchanged(),"selected missing manifest must be a real negative dependency");
}
#[test]
fn actual_keys_fixed_manifest_first_io_is_not_empty_order_and_fresh_recorder_recovers(){
 let root=initial_root("order");let physical=Physical{fail_policy:Mutex::new(Some(root.join("deepquarry.dme"))),reads:Mutex::new(BTreeMap::new())};let inputs=RecordingInputs::new(&physical,4_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let error=workspace_capture::capture_with_auxiliary(&front,&inputs,discover(&root,&inputs),&root.join("tools/ci/lint_scopes.toml"),&[WorkspaceAuxiliaryQuestion::Keys]).err().unwrap();assert_eq!(error.raw_os_error(),Some(1450));*physical.fail_policy.lock().unwrap()=None;let recovered=RecordingInputs::new(&physical,5_000_000_000);let front=frontend(&root,&recovered,&db);let capture=capture(&root,&front,&recovered,true);let current=snapshot(&front,&db,&recovered,&capture);current.with_native_keys(&current.tree,|data,_,_|{assert!(!data.sites().is_empty());Ok(())}).unwrap();
}

#[test]
fn actual_keys_compiled_fixed_manifest_reuses_genuine_native_original_acquisition(){
 let root=initial_root("basic");std::fs::write(root.join("deepquarry.dme"),b"#include \"code/0000.dm\"\n").unwrap();
 let physical=Physical{fail_policy:Mutex::new(None),reads:Mutex::new(BTreeMap::new())};let inputs=RecordingInputs::new(&physical,4_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=dm_tree::frontend::build(&root.join("deepquarry.dme"),&inputs,&Default::default(),1).unwrap().with_body_queries(db.clone());let manifest_reads=||physical.reads.lock().unwrap().iter().filter(|(path,_)|path.file_name().is_some_and(|name|name=="deepquarry.dme")).map(|(_,count)|*count).sum::<usize>();let before=manifest_reads();let capture=capture(&root,&front,&inputs,true);assert_eq!(manifest_reads(),before,"fixed original already acquired by actual native compiler must be loaned");let current=snapshot(&front,&db,&inputs,&capture);current.with_native_keys(&current.tree,|data,_,_|{assert_eq!(data.sites().len(),16);Ok(())}).unwrap();assert_eq!(manifest_reads(),before);
}
